PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (
 id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, display_name TEXT NOT NULL,
 timezone TEXT NOT NULL DEFAULT 'Europe/Madrid', theme TEXT NOT NULL DEFAULT 'system' CHECK(theme IN ('light','dark','system')),
 preferred_task_view TEXT NOT NULL DEFAULT 'board' CHECK(preferred_task_view IN ('board','table')), week_start_day INTEGER NOT NULL DEFAULT 1 CHECK(week_start_day IN (0,1)), created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, owner_user_id TEXT NOT NULL UNIQUE REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workspace_members (workspace_id TEXT NOT NULL REFERENCES workspaces(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('owner','admin','member')), created_at TEXT NOT NULL, PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS sessions (id_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf_token TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS strategic_goals (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',period_start TEXT,period_end TEXT,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','achieved','paused','archived')),sort_order REAL NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),name TEXT NOT NULL,slug TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',goal_id TEXT,color TEXT NOT NULL DEFAULT '#39786b',icon TEXT NOT NULL DEFAULT 'folder',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','on_hold','archived')),target_date TEXT,sort_order REAL NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(workspace_id,slug),UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,goal_id) REFERENCES strategic_goals(workspace_id,id));
CREATE TABLE IF NOT EXISTS milestones (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',project_id TEXT,goal_id TEXT,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','achieved')),achieved_at TEXT,sort_order REAL NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id),FOREIGN KEY(workspace_id,goal_id) REFERENCES strategic_goals(workspace_id,id));
CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',project_id TEXT,parent_task_id TEXT,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','in_progress','pending_review','waiting_external','blocked','completed','cancelled')),priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','critical')),due_at TEXT,waiting_on TEXT NOT NULL DEFAULT '',follow_up_at TEXT,completed_at TEXT,cancelled_at TEXT,deleted_at TEXT,created_by_user_id TEXT NOT NULL REFERENCES users(id),sort_order REAL NOT NULL DEFAULT 0,tags TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id),FOREIGN KEY(workspace_id,parent_task_id) REFERENCES tasks(workspace_id,id));
CREATE TABLE IF NOT EXISTS task_events (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,task_id TEXT NOT NULL,actor_user_id TEXT NOT NULL REFERENCES users(id),event_type TEXT NOT NULL,from_value_json TEXT,to_value_json TEXT,occurred_at TEXT NOT NULL,FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id));
CREATE TABLE IF NOT EXISTS journal_entries (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),author_user_id TEXT NOT NULL REFERENCES users(id),entry_date TEXT NOT NULL,title TEXT NOT NULL DEFAULT '',revision INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(workspace_id,author_user_id,entry_date),UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS journal_blocks (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,journal_entry_id TEXT NOT NULL,block_type TEXT NOT NULL CHECK(block_type IN ('heading','paragraph','bullet','task_reference')),text_content TEXT NOT NULL DEFAULT '',task_id TEXT,indent_level INTEGER NOT NULL DEFAULT 0 CHECK(indent_level BETWEEN 0 AND 8),sort_order REAL NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(workspace_id,journal_entry_id) REFERENCES journal_entries(workspace_id,id),FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id));
CREATE TABLE IF NOT EXISTS focus_items (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),task_id TEXT NOT NULL,period_type TEXT NOT NULL CHECK(period_type IN ('daily','weekly')),period_start TEXT NOT NULL,sort_order REAL NOT NULL DEFAULT 0,created_at TEXT NOT NULL,UNIQUE(user_id,task_id,period_type,period_start),FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id));
CREATE TABLE IF NOT EXISTS idempotency_keys (workspace_id TEXT NOT NULL REFERENCES workspaces(id),request_id TEXT NOT NULL,result_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,request_id));
CREATE INDEX IF NOT EXISTS task_state ON tasks(workspace_id,status,priority);
CREATE INDEX IF NOT EXISTS events_period ON task_events(workspace_id,occurred_at);
CREATE INDEX IF NOT EXISTS events_task ON task_events(task_id,occurred_at);
CREATE INDEX IF NOT EXISTS journal_date ON journal_entries(author_user_id,entry_date);
CREATE INDEX IF NOT EXISTS focus_period ON focus_items(user_id,period_type,period_start);
